/// Closed vocabulary for failures returned by a production accelerator FEM
/// run.  Keeping this separate from the human-readable error preserves the
/// stage even when the underlying CUDA driver changes its message.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FemBackendFailureStage {
    Initialization,
    Admission,
    Setup,
    Allocation,
    Launch,
    Synchronization,
    Cancellation,
    NonConvergence,
    Teardown,
    Publication,
}

impl FemBackendFailureStage {
    pub const fn label(self) -> &'static str {
        match self {
            Self::Initialization => "initialization",
            Self::Admission => "admission",
            Self::Setup => "setup",
            Self::Allocation => "allocation",
            Self::Launch => "launch",
            Self::Synchronization => "synchronization",
            Self::Cancellation => "cancellation",
            Self::NonConvergence => "non-convergence",
            Self::Teardown => "teardown",
            Self::Publication => "publication",
        }
    }
}

/// Recovery action required before a failed CUDA context can be used again.
///
/// The room runner owns all device buffers locally.  Thus a failure always
/// drops those resources during error unwinding; only native execution errors
/// need a stronger context boundary than ordinary setup failures.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FemBackendContextRecovery {
    Reusable,
    SynchronizeBeforeReuse,
    Recreate,
}

impl FemBackendContextRecovery {
    pub const fn label(self) -> &'static str {
        match self {
            Self::Reusable => "reusable",
            Self::SynchronizeBeforeReuse => "synchronize-before-reuse",
            Self::Recreate => "recreate",
        }
    }
}

/// Structured provenance attached to every production CUDA FEM error exit.
///
/// `partial_result_published` is deliberately always false for this runner:
/// listener pressures and diagnostics are local until the final success tuple
/// is constructed. `resources_released_on_unwind` documents the ownership
/// contract of the local backend/buffer values rather than pretending that a
/// driver-level leak counter exists.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FemBackendFailureDiagnostics {
    pub backend: String,
    pub stage: FemBackendFailureStage,
    pub operation: String,
    pub detail: String,
    pub frequency_index: Option<usize>,
    pub source_index: Option<usize>,
    pub partial_result_published: bool,
    pub resources_released_on_unwind: bool,
    pub context_recovery: FemBackendContextRecovery,
}

impl std::fmt::Display for FemBackendFailureDiagnostics {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            formatter,
            "{} FEM failure at {} ({}): {} [partial_result_published={}, resources_released_on_unwind={}, context_recovery={}]",
            self.backend,
            self.stage.label(),
            self.operation,
            self.detail,
            self.partial_result_published,
            self.resources_released_on_unwind,
            self.context_recovery.label(),
        )
    }
}

impl std::error::Error for FemBackendFailureDiagnostics {}

impl FemBackendFailureDiagnostics {
    /// Convert any error from the CUDA runner into a stable stage record.
    ///
    /// This is intentionally centralized at the runner boundary. It covers
    /// errors returned by helper crates as well as the room runner's own typed
    /// errors, so a newly added `?` cannot silently escape without structured
    /// failure provenance.
    pub fn from_error(error: &anyhow::Error) -> Self {
        let (stage, operation, context_recovery) =
            if let Some(error_kind) = error.downcast_ref::<FemBackendExecutionError>() {
                match error_kind {
                    FemBackendExecutionError::UnsupportedNativePrimitive { .. } => (
                        FemBackendFailureStage::Admission,
                        "native-capability-admission".to_string(),
                        FemBackendContextRecovery::Reusable,
                    ),
                    FemBackendExecutionError::DeviceUnavailable { .. } => (
                        FemBackendFailureStage::Initialization,
                        "cuda-device-initialization".to_string(),
                        FemBackendContextRecovery::Reusable,
                    ),
                    FemBackendExecutionError::Cancelled { .. } => (
                        FemBackendFailureStage::Cancellation,
                        "cooperative-cancellation".to_string(),
                        FemBackendContextRecovery::Reusable,
                    ),
                    FemBackendExecutionError::PhysicalEvidence { .. } => (
                        FemBackendFailureStage::Publication,
                        "physical-evidence-publication".to_string(),
                        FemBackendContextRecovery::SynchronizeBeforeReuse,
                    ),
                }
            } else if let Some(error_kind) = error.downcast_ref::<sonium_compute::BackendError>() {
                match error_kind {
                    sonium_compute::BackendError::DeviceLost { operation, .. } => (
                        FemBackendFailureStage::Setup,
                        operation.to_string(),
                        FemBackendContextRecovery::Recreate,
                    ),
                    sonium_compute::BackendError::Launch { operation, .. } => (
                        FemBackendFailureStage::Launch,
                        operation.to_string(),
                        FemBackendContextRecovery::SynchronizeBeforeReuse,
                    ),
                    sonium_compute::BackendError::Synchronization { operation, .. }
                    | sonium_compute::BackendError::CommandBuffer { operation, .. } => (
                        FemBackendFailureStage::Synchronization,
                        operation.to_string(),
                        FemBackendContextRecovery::Recreate,
                    ),
                    sonium_compute::BackendError::Transfer { operation, .. } => (
                        FemBackendFailureStage::Setup,
                        operation.to_string(),
                        FemBackendContextRecovery::SynchronizeBeforeReuse,
                    ),
                    sonium_compute::BackendError::Allocation { .. } => (
                        FemBackendFailureStage::Allocation,
                        "cuda-device-allocation".to_string(),
                        FemBackendContextRecovery::Reusable,
                    ),
                    sonium_compute::BackendError::OperationFailed { operation, .. } => (
                        FemBackendFailureStage::Setup,
                        operation.to_string(),
                        FemBackendContextRecovery::SynchronizeBeforeReuse,
                    ),
                    sonium_compute::BackendError::Unsupported { operation, .. }
                    | sonium_compute::BackendError::HostFallback { operation, .. }
                    | sonium_compute::BackendError::InvalidArgument { operation, .. } => (
                        FemBackendFailureStage::Setup,
                        operation.to_string(),
                        FemBackendContextRecovery::Reusable,
                    ),
                }
            } else {
                let detail = error.to_string().to_ascii_lowercase();
                if detail.contains("device lost") || detail.contains("device loss") {
                    (
                        FemBackendFailureStage::Setup,
                        "cuda_device_loss".to_string(),
                        FemBackendContextRecovery::Recreate,
                    )
                } else if detail.contains("cancel") {
                    (
                        FemBackendFailureStage::Cancellation,
                        "cooperative-cancellation".to_string(),
                        FemBackendContextRecovery::Reusable,
                    )
                } else if detail.contains("cuda_solver_nonconvergence") {
                    (
                        FemBackendFailureStage::NonConvergence,
                        "cuda_solver_nonconvergence".to_string(),
                        FemBackendContextRecovery::SynchronizeBeforeReuse,
                    )
                } else if detail.contains("nonconver")
                    || detail.contains("did not converge")
                    || detail.contains("convergence")
                {
                    (
                        FemBackendFailureStage::NonConvergence,
                        "solver-convergence".to_string(),
                        FemBackendContextRecovery::SynchronizeBeforeReuse,
                    )
                } else if detail.contains("synchron") || detail.contains("stream") {
                    (
                        FemBackendFailureStage::Synchronization,
                        "cuda-stream-synchronization".to_string(),
                        FemBackendContextRecovery::Recreate,
                    )
                } else if detail.contains("launch")
                    || detail.contains("kernel")
                    || detail.contains("spmv")
                    || detail.contains("gmres")
                    || detail.contains("solve failed")
                {
                    (
                        FemBackendFailureStage::Launch,
                        "cuda-kernel-launch".to_string(),
                        FemBackendContextRecovery::SynchronizeBeforeReuse,
                    )
                } else if detail.contains("alloc")
                    || detail.contains("out of memory")
                    || detail.contains("memory budget")
                {
                    (
                        FemBackendFailureStage::Allocation,
                        "cuda-device-allocation".to_string(),
                        FemBackendContextRecovery::Reusable,
                    )
                } else if detail.contains("publish") || detail.contains("physical evidence") {
                    (
                        FemBackendFailureStage::Publication,
                        "result-publication".to_string(),
                        FemBackendContextRecovery::SynchronizeBeforeReuse,
                    )
                } else if detail.contains("drop") || detail.contains("teardown") {
                    (
                        FemBackendFailureStage::Teardown,
                        "cuda-resource-teardown".to_string(),
                        FemBackendContextRecovery::Recreate,
                    )
                } else if detail.contains("valid")
                    || detail.contains("geometry")
                    || detail.contains("frequency")
                {
                    (
                        FemBackendFailureStage::Initialization,
                        "fem-input-initialization".to_string(),
                        FemBackendContextRecovery::Reusable,
                    )
                } else {
                    (
                        FemBackendFailureStage::Setup,
                        "cuda-fem-setup".to_string(),
                        FemBackendContextRecovery::Reusable,
                    )
                }
            };

        Self {
            backend: "cuda".to_string(),
            stage,
            operation: operation.to_string(),
            detail: error.to_string(),
            frequency_index: None,
            source_index: None,
            partial_result_published: false,
            resources_released_on_unwind: true,
            context_recovery,
        }
    }

    /// Attach a structured diagnostic while retaining the original typed
    /// error in the anyhow source chain for compatibility callers.
    pub fn attach(error: anyhow::Error) -> anyhow::Error {
        let diagnostic = Self::from_error(&error);
        // `anyhow::Context` is implemented for Result/Option rather than for
        // `anyhow::Error` itself.  Wrapping a never-successful Result keeps
        // the original typed error in the source chain and makes both the
        // diagnostic and legacy error downcasts work.
        Err::<(), _>(error).context(diagnostic).unwrap_err()
    }
}

/// Typed failures emitted by accelerator FEM setup and control paths.
///
/// The public runner still returns `anyhow::Error` for compatibility, but
/// callers can downcast that error to distinguish an unsupported native
/// primitive, unavailable hardware, and cooperative cancellation from an
/// ordinary solver failure.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FemBackendExecutionError {
    /// The requested backend cannot keep a required primitive device-native.
    UnsupportedNativePrimitive {
        backend: String,
        precision: String,
        operation: String,
        capability: String,
    },
    /// Backend initialization or device discovery failed.
    DeviceUnavailable { backend: String, detail: String },
    /// The caller cancelled the run at a frequency boundary or setup point.
    Cancelled { backend: String, reason: String },
    /// A solved device field could not be converted into the required ledger.
    PhysicalEvidence { backend: String, detail: String },
}

impl std::fmt::Display for FemBackendExecutionError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::UnsupportedNativePrimitive {
                backend,
                precision,
                operation,
                capability,
            } => write!(
                formatter,
                "{backend} FEM requested native execution with {precision} precision, but {operation} is {capability}"
            ),
            Self::DeviceUnavailable { backend, detail } => {
                write!(formatter, "{backend} FEM device unavailable: {detail}")
            }
            Self::Cancelled { backend, reason } => {
                write!(formatter, "{backend} FEM run cancelled: {reason}")
            }
            Self::PhysicalEvidence { backend, detail } => {
                write!(
                    formatter,
                    "{backend} FEM physical evidence failed: {detail}"
                )
            }
        }
    }
}

impl std::error::Error for FemBackendExecutionError {}

/// Describes whether a FEM diagnostic packet carries physical-domain energy
/// evidence. Reduced-domain and intentionally incomplete packets retain
/// explicit states so consumers cannot mistake missing ledgers for zero work.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FemPhysicalEvidenceStatus {
    /// No physical evidence has been collected yet.
    NotCollected,
    /// Every frequency carries all physical evidence ledgers.
    Complete,
    /// A packet contains only part of the required evidence.
    Incomplete,
    /// Symmetry reduction has no promoted full-domain energy reconstruction.
    UnavailableReducedDomain,
    /// An intentionally incomplete device packet has no physical evidence.
    /// Production device solves must publish complete ledgers instead.
    UnavailableDeviceBackend,
}

/// Machine-readable execution provenance for one FEM run.
///
/// A successful accelerator result must identify both the requested and
/// actual backend. `fallback_status` is intentionally explicit so a host
/// staging path cannot be mistaken for device-resident execution. Memory
/// fields are estimates supplied by the backend runner; transfer counters are
/// checked backend observations.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FemExecutionEvidence {
    pub requested_backend: String,
    pub actual_backend: String,
    pub precision: String,
    pub fallback_status: String,
    pub host_architecture: String,
    pub cpu_simd_backend: Option<String>,
    pub setup_transfer_stats: FemTransferStats,
    pub total_transfer_stats: FemTransferStats,
    pub estimated_peak_memory_bytes: Option<u64>,
    pub device_free_memory_bytes: Option<u64>,
    pub device_total_memory_bytes: Option<u64>,
}

impl FemExecutionEvidence {
    fn for_backend(backend: &str) -> Self {
        let is_cpu = backend.starts_with("cpu");
        Self {
            requested_backend: backend.to_string(),
            actual_backend: backend.to_string(),
            precision: if is_cpu { "f64" } else { "unspecified" }.to_string(),
            fallback_status: "none".to_string(),
            host_architecture: std::env::consts::ARCH.to_string(),
            cpu_simd_backend: is_cpu
                .then(|| sonium_fastmath::selected_backend().as_str().to_string()),
            setup_transfer_stats: FemTransferStats::default(),
            total_transfer_stats: FemTransferStats::default(),
            estimated_peak_memory_bytes: None,
            device_free_memory_bytes: None,
            device_total_memory_bytes: None,
        }
    }

    #[cfg(any(feature = "cuda", feature = "metal"))]
    pub(super) fn set_profile(
        &mut self,
        requested_backend: &str,
        actual_backend: &str,
        precision: &str,
        fallback_status: &str,
    ) {
        self.requested_backend = requested_backend.to_string();
        self.actual_backend = actual_backend.to_string();
        self.precision = precision.to_string();
        self.fallback_status = fallback_status.to_string();
        self.cpu_simd_backend = None;
    }

    #[cfg(any(feature = "cuda", feature = "metal"))]
    pub(super) fn set_memory(
        &mut self,
        estimated_peak_memory_bytes: u64,
        device_free_memory_bytes: Option<u64>,
        device_total_memory_bytes: Option<u64>,
    ) {
        self.estimated_peak_memory_bytes = Some(estimated_peak_memory_bytes);
        self.device_free_memory_bytes = device_free_memory_bytes;
        self.device_total_memory_bytes = device_total_memory_bytes;
    }

    #[cfg(any(feature = "cuda", feature = "metal"))]
    pub(super) fn set_transfers(
        &mut self,
        setup_transfer_stats: FemTransferStats,
        total_transfer_stats: FemTransferStats,
    ) {
        self.setup_transfer_stats = setup_transfer_stats;
        self.total_transfer_stats = total_transfer_stats;
    }

    fn validate(&self) -> Result<(), String> {
        if self.requested_backend.trim().is_empty()
            || self.actual_backend.trim().is_empty()
            || self.precision.trim().is_empty()
            || self.fallback_status.trim().is_empty()
            || self.host_architecture.trim().is_empty()
        {
            return Err("FEM execution evidence requires backend, precision, fallback, and architecture labels".into());
        }
        if self
            .estimated_peak_memory_bytes
            .is_some_and(|bytes| bytes == 0)
        {
            return Err("FEM execution estimated peak memory must be positive".into());
        }
        if self.fallback_status == "none" && self.requested_backend != self.actual_backend {
            return Err(
                "FEM execution requested and actual backends differ without fallback provenance"
                    .into(),
            );
        }
        match (
            self.device_free_memory_bytes,
            self.device_total_memory_bytes,
        ) {
            (Some(free), Some(total)) if free <= total && total > 0 => {}
            (None, None) | (Some(_), None) | (None, Some(_)) => {}
            (Some(_), Some(_)) => {
                return Err("FEM execution device memory bounds are invalid".into());
            }
        }
        Ok(())
    }
}

impl FemPhysicalEvidenceStatus {
    pub(crate) fn label(self) -> &'static str {
        match self {
            Self::NotCollected => "not-collected",
            Self::Complete => "complete",
            Self::Incomplete => "incomplete",
            Self::UnavailableReducedDomain => "unavailable-reduced-domain",
            Self::UnavailableDeviceBackend => "unavailable-device-backend",
        }
    }
}

fn has_complete_physical_evidence(stats: &FemFrequencyStats) -> bool {
    stats.operator_work.is_some() && stats.physical_power.is_some() && stats.boundary_flux.is_some()
}

fn has_any_physical_evidence(stats: &FemFrequencyStats) -> bool {
    stats.operator_work.is_some() || stats.physical_power.is_some() || stats.boundary_flux.is_some()
}

#[derive(Debug, Clone)]
pub struct FemRunDiagnostics {
    pub backend: String,
    pub preconditioner: String,
    pub shift: ShiftedLaplacianShift,
    pub modal_damping_ratio: f64,
    pub total_iterations: usize,
    pub total_inner_iterations: usize,
    pub retry_count: usize,
    pub nonconverged_count: usize,
    /// Listening positions that missed every mesh element and were sampled
    /// with the nearest-node fallback instead of barycentric interpolation.
    pub listener_interpolation_fallbacks: usize,
    pub max_residual: f64,
    /// Explicit provenance for omitted physical-domain energy evidence.
    pub physical_evidence_status: FemPhysicalEvidenceStatus,
    /// Backend, architecture, memory, and transfer provenance.
    pub execution: Option<FemExecutionEvidence>,
    pub frequency_stats: Vec<FemFrequencyStats>,
}

impl FemRunDiagnostics {
    pub(super) fn new(backend: &str, mesh_config: &FemMeshConfig) -> Self {
        Self::new_with_preconditioner(
            backend,
            mesh_config.preconditioner.to_string(),
            mesh_config.shifted_laplacian_shift,
            mesh_config.modal_damping_ratio,
        )
    }

    pub(super) fn new_with_preconditioner(
        backend: &str,
        preconditioner: String,
        shift: ShiftedLaplacianShift,
        modal_damping_ratio: f64,
    ) -> Self {
        Self {
            backend: backend.to_string(),
            preconditioner,
            shift,
            modal_damping_ratio,
            total_iterations: 0,
            total_inner_iterations: 0,
            retry_count: 0,
            nonconverged_count: 0,
            listener_interpolation_fallbacks: 0,
            max_residual: 0.0,
            physical_evidence_status: FemPhysicalEvidenceStatus::NotCollected,
            execution: Some(FemExecutionEvidence::for_backend(backend)),
            frequency_stats: Vec::new(),
        }
    }

    pub(super) fn mark_reduced_domain_physical_evidence_unavailable(&mut self) {
        self.physical_evidence_status = FemPhysicalEvidenceStatus::UnavailableReducedDomain;
    }

    #[cfg(any(feature = "cuda", feature = "metal", test))]
    #[cfg(test)]
    pub(super) fn mark_device_physical_evidence_unavailable(&mut self) {
        self.physical_evidence_status = FemPhysicalEvidenceStatus::UnavailableDeviceBackend;
    }

    pub(super) fn record_frequency(&mut self, stats: FemFrequencyStats) {
        self.total_iterations += stats.iterations;
        self.total_inner_iterations += stats.inner_iterations;
        self.retry_count += stats.retries;
        if !stats.converged {
            self.nonconverged_count += 1;
        }
        self.max_residual = self.max_residual.max(stats.max_residual);
        let has_any = has_any_physical_evidence(&stats);
        let has_complete = has_complete_physical_evidence(&stats);
        match self.physical_evidence_status {
            FemPhysicalEvidenceStatus::NotCollected if has_complete => {
                self.physical_evidence_status = FemPhysicalEvidenceStatus::Complete;
            }
            FemPhysicalEvidenceStatus::NotCollected if has_any => {
                self.physical_evidence_status = FemPhysicalEvidenceStatus::Incomplete;
            }
            FemPhysicalEvidenceStatus::Complete if !has_complete => {
                self.physical_evidence_status = FemPhysicalEvidenceStatus::Incomplete;
            }
            FemPhysicalEvidenceStatus::Incomplete
            | FemPhysicalEvidenceStatus::UnavailableReducedDomain
            | FemPhysicalEvidenceStatus::UnavailableDeviceBackend
            | FemPhysicalEvidenceStatus::NotCollected
            | FemPhysicalEvidenceStatus::Complete => {}
        }
        self.frequency_stats.push(stats);
    }

    #[cfg(any(feature = "cuda", feature = "metal"))]
    pub(super) fn set_execution_profile(
        &mut self,
        requested_backend: &str,
        actual_backend: &str,
        precision: &str,
        fallback_status: &str,
    ) {
        if let Some(execution) = self.execution.as_mut() {
            execution.set_profile(
                requested_backend,
                actual_backend,
                precision,
                fallback_status,
            );
        }
    }

    #[cfg(any(feature = "cuda", feature = "metal"))]
    pub(super) fn set_execution_memory(
        &mut self,
        estimated_peak_memory_bytes: u64,
        device_free_memory_bytes: Option<u64>,
        device_total_memory_bytes: Option<u64>,
    ) {
        if let Some(execution) = self.execution.as_mut() {
            execution.set_memory(
                estimated_peak_memory_bytes,
                device_free_memory_bytes,
                device_total_memory_bytes,
            );
        }
    }

    #[cfg(any(feature = "cuda", feature = "metal"))]
    pub(super) fn set_execution_transfers(
        &mut self,
        setup_transfer_stats: FemTransferStats,
        total_transfer_stats: FemTransferStats,
    ) {
        if let Some(execution) = self.execution.as_mut() {
            execution.set_transfers(setup_transfer_stats, total_transfer_stats);
        }
    }

    /// Validate diagnostic counters before they are used as physical evidence.
    pub fn validate(&self) -> Result<(), String> {
        if self.backend.trim().is_empty() || self.preconditioner.trim().is_empty() {
            return Err("FEM diagnostics require backend and preconditioner labels".into());
        }
        if !self.modal_damping_ratio.is_finite() || self.modal_damping_ratio < 0.0 {
            return Err(
                "FEM diagnostics modal damping ratio must be finite and non-negative".into(),
            );
        }
        if !self.max_residual.is_finite() || self.max_residual < 0.0 {
            return Err("FEM diagnostics maximum residual must be finite and non-negative".into());
        }
        if self.frequency_stats.is_empty() {
            return Err("FEM diagnostics require at least one frequency statistic".into());
        }
        if let Some(execution) = &self.execution {
            execution.validate()?;
            if matches!(execution.actual_backend.as_str(), "cuda" | "metal") {
                if execution.estimated_peak_memory_bytes.is_none() {
                    return Err("accelerator FEM execution requires peak-memory provenance".into());
                }
                if self
                    .frequency_stats
                    .iter()
                    .any(|stats| stats.transfer_stats.is_none())
                {
                    return Err(
                        "accelerator FEM execution requires transfer provenance for every frequency"
                            .into(),
                    );
                }
                if execution.actual_backend == "cuda"
                    && self
                        .frequency_stats
                        .iter()
                        .any(|stats| stats.allocation_high_water_bytes == 0)
                {
                    return Err(
                        "CUDA FEM execution requires allocation high-water provenance for every frequency"
                            .into(),
                    );
                }
            }
        }

        let mut total_iterations = 0usize;
        let mut total_inner_iterations = 0usize;
        let mut retry_count = 0usize;
        let mut nonconverged_count = 0usize;
        let mut max_residual = 0.0f64;
        for stats in &self.frequency_stats {
            if !stats.frequency_hz.is_finite()
                || stats.frequency_hz <= 0.0
                || !stats.matrix_ms.is_finite()
                || stats.matrix_ms < 0.0
                || !stats.preconditioner_ms.is_finite()
                || stats.preconditioner_ms < 0.0
                || !stats.rhs_ms.is_finite()
                || stats.rhs_ms < 0.0
                || !stats.solve_ms.is_finite()
                || stats.solve_ms < 0.0
                || !stats.max_residual.is_finite()
                || stats.max_residual < 0.0
            {
                return Err(
                    "FEM frequency diagnostics contain a non-finite or negative metric".into(),
                );
            }
            if let Some(operator_work) = stats.operator_work {
                operator_work
                    .validate()
                    .map_err(|error| format!("invalid FEM operator-work evidence: {error}"))?;
            }
            if let Some(physical_power) = stats.physical_power {
                physical_power
                    .validate()
                    .map_err(|error| format!("invalid FEM physical-power evidence: {error}"))?;
                if stats.operator_work.is_none() {
                    return Err(
                        "FEM physical-power evidence requires operator-work evidence".into(),
                    );
                }
            }
            if let Some(boundary_flux) = stats.boundary_flux.as_ref() {
                boundary_flux
                    .validate()
                    .map_err(|error| format!("invalid FEM boundary-flux evidence: {error}"))?;
                let physical_power = stats.physical_power.ok_or_else(|| {
                    "FEM boundary-flux evidence requires physical-power evidence".to_string()
                })?;
                let tolerance = 1.0e-10
                    * physical_power
                        .boundary_power_w
                        .abs()
                        .max(boundary_flux.total_power_w.abs())
                        .max(1.0);
                if (boundary_flux.total_power_w - physical_power.boundary_power_w).abs() > tolerance
                {
                    return Err(
                        "FEM boundary-flux total disagrees with physical-power boundary term"
                            .into(),
                    );
                }
            }
            let has_any = has_any_physical_evidence(stats);
            let has_complete = has_complete_physical_evidence(stats);
            if has_any && !has_complete {
                return Err(
                    "FEM physical evidence must include operator-work, physical-power, and boundary-flux ledgers"
                        .into(),
                );
            }
            match self.physical_evidence_status {
                FemPhysicalEvidenceStatus::NotCollected if has_any => {
                    return Err(
                        "FEM diagnostics marked physical evidence not-collected but contain evidence"
                            .into(),
                    );
                }
                FemPhysicalEvidenceStatus::Complete if !has_complete => {
                    return Err(
                        "FEM diagnostics marked physical evidence complete but a frequency is missing evidence"
                            .into(),
                    );
                }
                FemPhysicalEvidenceStatus::Incomplete => {
                    return Err("FEM diagnostics contain incomplete physical evidence".into());
                }
                FemPhysicalEvidenceStatus::UnavailableReducedDomain if has_any => {
                    return Err(
                        "reduced-domain FEM diagnostics cannot contain physical-domain evidence"
                            .into(),
                    );
                }
                FemPhysicalEvidenceStatus::UnavailableDeviceBackend if has_any => {
                    return Err(
                        "device FEM diagnostics cannot contain host physical-domain evidence"
                            .into(),
                    );
                }
                FemPhysicalEvidenceStatus::NotCollected
                | FemPhysicalEvidenceStatus::Complete
                | FemPhysicalEvidenceStatus::UnavailableReducedDomain
                | FemPhysicalEvidenceStatus::UnavailableDeviceBackend => {}
            }

            total_iterations = total_iterations
                .checked_add(stats.iterations)
                .ok_or_else(|| "FEM diagnostics iteration counter overflowed".to_string())?;
            total_inner_iterations = total_inner_iterations
                .checked_add(stats.inner_iterations)
                .ok_or_else(|| "FEM diagnostics inner-iteration counter overflowed".to_string())?;
            retry_count = retry_count
                .checked_add(stats.retries)
                .ok_or_else(|| "FEM diagnostics retry counter overflowed".to_string())?;
            nonconverged_count += usize::from(!stats.converged);
            max_residual = max_residual.max(stats.max_residual);
        }
        if self.total_iterations != total_iterations
            || self.total_inner_iterations != total_inner_iterations
            || self.retry_count != retry_count
            || self.nonconverged_count != nonconverged_count
            || self.max_residual != max_residual
        {
            return Err(
                "FEM diagnostics aggregate counters do not match frequency statistics".into(),
            );
        }
        Ok(())
    }

    /// Require every accepted frequency statistic to have converged.
    pub fn require_converged(&self) -> Result<(), String> {
        self.validate()?;
        if self.nonconverged_count != 0 {
            return Err(format!(
                "FEM solve has {} nonconverged frequency result(s); physical output is not accepted",
                self.nonconverged_count
            ));
        }
        if self.frequency_stats.iter().any(|stats| !stats.converged) {
            return Err(
                "FEM diagnostics nonconverged count is inconsistent with frequency statistics"
                    .into(),
            );
        }
        Ok(())
    }
}

#[cfg(test)]
mod failure_diagnostics_tests {
    use super::{
        FemBackendContextRecovery, FemBackendExecutionError, FemBackendFailureDiagnostics,
        FemBackendFailureStage,
    };

    fn error(message: &str) -> anyhow::Error {
        anyhow::anyhow!(message.to_string())
    }

    #[test]
    fn every_failure_class_maps_to_a_closed_stage_and_safe_publication() {
        let cases = [
            (
                anyhow::Error::new(FemBackendExecutionError::DeviceUnavailable {
                    backend: "cuda".into(),
                    detail: "driver unavailable".into(),
                }),
                FemBackendFailureStage::Initialization,
                FemBackendContextRecovery::Reusable,
            ),
            (
                anyhow::Error::new(FemBackendExecutionError::UnsupportedNativePrimitive {
                    backend: "cuda".into(),
                    precision: "f64".into(),
                    operation: "Complex64 SpMV".into(),
                    capability: "host fallback".into(),
                }),
                FemBackendFailureStage::Admission,
                FemBackendContextRecovery::Reusable,
            ),
            (
                error("GPU allocation failed for residual scratch"),
                FemBackendFailureStage::Allocation,
                FemBackendContextRecovery::Reusable,
            ),
            (
                error("CUDA kernel launch failed"),
                FemBackendFailureStage::Launch,
                FemBackendContextRecovery::SynchronizeBeforeReuse,
            ),
            (
                anyhow::Error::new(sonium_compute::BackendError::Launch {
                    backend: "cuda",
                    operation: "cuda_launch",
                    reason: "injected CUDA launch/event failure".into(),
                }),
                FemBackendFailureStage::Launch,
                FemBackendContextRecovery::SynchronizeBeforeReuse,
            ),
            (
                anyhow::Error::new(sonium_compute::BackendError::DeviceLost {
                    backend: "cuda",
                    operation: "cuda_device_loss",
                    reason: "injected CUDA device loss".into(),
                }),
                FemBackendFailureStage::Setup,
                FemBackendContextRecovery::Recreate,
            ),
            (
                error("CUDA stream synchronization failed"),
                FemBackendFailureStage::Synchronization,
                FemBackendContextRecovery::Recreate,
            ),
            (
                anyhow::Error::new(FemBackendExecutionError::Cancelled {
                    backend: "cuda".into(),
                    reason: "user requested stop".into(),
                }),
                FemBackendFailureStage::Cancellation,
                FemBackendContextRecovery::Reusable,
            ),
            (
                error("FEM did not converge after retry"),
                FemBackendFailureStage::NonConvergence,
                FemBackendContextRecovery::SynchronizeBeforeReuse,
            ),
            (
                error("physical evidence publication failed"),
                FemBackendFailureStage::Publication,
                FemBackendContextRecovery::SynchronizeBeforeReuse,
            ),
            (
                error("CUDA resource teardown failed"),
                FemBackendFailureStage::Teardown,
                FemBackendContextRecovery::Recreate,
            ),
            (
                error("listener setup failed"),
                FemBackendFailureStage::Setup,
                FemBackendContextRecovery::Reusable,
            ),
        ];

        for (error, expected_stage, expected_recovery) in cases {
            let diagnostic = FemBackendFailureDiagnostics::from_error(&error);
            assert_eq!(diagnostic.stage, expected_stage);
            assert_eq!(diagnostic.context_recovery, expected_recovery);
            assert_eq!(diagnostic.backend, "cuda");
            assert_eq!(diagnostic.frequency_index, None);
            assert_eq!(diagnostic.source_index, None);
            assert!(!diagnostic.partial_result_published);
            assert!(diagnostic.resources_released_on_unwind);
            assert!(!diagnostic.operation.is_empty());
            assert!(!diagnostic.detail.is_empty());
        }
    }

    #[test]
    fn attaching_diagnostics_preserves_legacy_typed_downcasts() {
        let error = anyhow::Error::new(FemBackendExecutionError::Cancelled {
            backend: "cuda".into(),
            reason: "cancelled before setup".into(),
        });
        let attached = FemBackendFailureDiagnostics::attach(error);
        assert!(
            attached
                .downcast_ref::<FemBackendFailureDiagnostics>()
                .is_some()
        );
        assert!(matches!(
            attached.downcast_ref::<FemBackendExecutionError>(),
            Some(FemBackendExecutionError::Cancelled { backend, reason })
                if backend == "cuda" && reason == "cancelled before setup"
        ));
    }

    #[test]
    fn stage_and_recovery_labels_are_stable_for_artifact_checkers() {
        assert_eq!(
            FemBackendFailureStage::NonConvergence.label(),
            "non-convergence"
        );
        assert_eq!(FemBackendFailureStage::Publication.label(), "publication");
        assert_eq!(
            FemBackendContextRecovery::SynchronizeBeforeReuse.label(),
            "synchronize-before-reuse"
        );
    }
}
